import{_ as t,o as n,c as o,a0 as a}from"./chunks/framework.L_oL6aia.js";const g=JSON.parse('{"title":"1. Workshop Introduction & Overview","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md"}'),i={name:"introduction.md"};function s(r,e,l,c,p,d){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="_1-workshop-introduction-overview" tabindex="-1">1. Workshop Introduction &amp; Overview <a class="header-anchor" href="#_1-workshop-introduction-overview" aria-label="Permalink to &quot;1. Workshop Introduction &amp; Overview&quot;">​</a></h1><p>Welcome to the <strong>Contoso PizzaBot</strong> AI agent workshop documentation! This guide documents the step-by-step implementation of an enterprise-grade, domain-specific AI assistant using the <strong>Microsoft Azure AI Foundry Agent Service</strong> and the <strong>Model Context Protocol (MCP)</strong>.</p><p>Built during the Microsoft HQ OpenHack workshop, this showcase demonstrates how to bridge LLMs with real-world private data and external service systems securely and efficiently.</p><hr><h2 id="what-we-are-building-contoso-pizzabot-🍕🤖" tabindex="-1">What We Are Building: Contoso PizzaBot 🍕🤖 <a class="header-anchor" href="#what-we-are-building-contoso-pizzabot-🍕🤖" aria-label="Permalink to &quot;What We Are Building: Contoso PizzaBot 🍕🤖&quot;">​</a></h2><p>The goal of this project is to create <strong>Contoso PizzaBot</strong>, a conversational agent that acts as a friendly, Gen Alpha-styled ordering assistant. Unlike a generic chatbot, PizzaBot is integrated into Contoso Pizza’s backend systems to answer store queries, recommend order sizes, and place real orders.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User([User Chat Interface]) &lt;--&gt; Loop[Agent Conversation Loop]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Loop &lt;--&gt; Client[Azure AI Project Client]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client &lt;--&gt; AgentService[Azure AI Agent Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Azure AI Foundry Tools</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        AgentService &lt;--&gt; RAG[File Search RAG Vector Store]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        AgentService &lt;--&gt; LocalFunc[Local Function Tool: calculate_pizza_order]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        AgentService &lt;--&gt; MCP[MCP Tool: contoso-pizza-mcp SSE]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RAG --&gt; Stores[(Store Markdown Grounding Docs)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MCP --&gt; ContainerApp[Azure Container Apps Pizza API]</span></span></code></pre></div><h3 id="core-capabilities" tabindex="-1">Core Capabilities: <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core Capabilities:&quot;">​</a></h3><ol><li><strong>Dynamic Persona &amp; Guardrails</strong>: Configured with strict rules to keep discussions focused on pizzas, handle Pineapple-on-pizza snark playfully, and require user confirmations before processing transactions.</li><li><strong>Retrieval-Augmented Generation (RAG)</strong>: Connects to an Azure Vector Store containing localized markdown files for branches (Boston, Amsterdam, Sao Paulo, San Francisco, etc.) to query hours, addresses, and physical store menus.</li><li><strong>Deterministic Function Tools</strong>: Calls local Python code to calculate pizza order quantities based on group sizes.</li><li><strong>Model Context Protocol (MCP)</strong>: Integrates over Server-Sent Events (SSE) to a live Container Apps service to query real-time toppings, place new orders, track status, or execute cancellations.</li></ol><hr><h2 id="key-skills-concepts-covered" tabindex="-1">Key Skills &amp; Concepts Covered <a class="header-anchor" href="#key-skills-concepts-covered" aria-label="Permalink to &quot;Key Skills &amp; Concepts Covered&quot;">​</a></h2><p>Through this project, you will learn and apply:</p><ul><li><strong>Azure AI Foundry Client SDK</strong>: Initializing <a href="./agent.py.html#L12"><code>AIProjectClient</code></a> and orchestrating assistants and runs.</li><li><strong>RAG &amp; Semantic Indexing</strong>: Setting up, uploading documents to, and querying vector stores using <a href="./agent.py.html#L7"><code>FileSearchTool</code></a>.</li><li><strong>Strict Schema Tooling</strong>: Exposing Python helper functions to the model with strict JSON validations using <a href="./agent.py.html#L7"><code>FunctionTool</code></a>.</li><li><strong>MCP Integration</strong>: Using the new industry-standard Model Context Protocol via <a href="./agent.py.html#L7"><code>MCPTool</code></a> to avoid custom API boilerplate.</li><li><strong>Agent Loop Execution</strong>: Managing stateful multi-turn runs, handling function call intermediate executions, and handling thread states.</li></ul><hr><h2 id="document-site-roadmap" tabindex="-1">Document Site Roadmap <a class="header-anchor" href="#document-site-roadmap" aria-label="Permalink to &quot;Document Site Roadmap&quot;">​</a></h2><ol><li><strong><a href="./introduction.html">1. Introduction &amp; Overview</a></strong> (This page)</li><li><strong><a href="./setup-environment.html">2. Environment &amp; Azure Setup</a></strong>: Authenticating, setting up the Azure Resource Group, deploying models, and loading variables.</li><li><strong><a href="./building-agent.html">3. Building Your First Agent</a></strong>: Creating the agent, setting system instructions, and enabling File Search (RAG) using your local store docs in <code>docs/contoso-stores/</code>.</li><li><strong><a href="./tool-calling-mcp.html">4. Tools &amp; MCP Integration</a></strong>: Activating function tools, hooking into SSE MCP server endpoints, handling conversational loops, and testing live pizza ordering.</li></ol>`,16)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
